/** The lock block for one role in one note form; null for a key that is not one of the pack's roles. */
export function uzSoapKilidi(dil: UzNotDili, rol: string): string | null {
  const g = Object.prototype.hasOwnProperty.call(UZ_SOAP_ROL_GRUBU, rol) ? G[UZ_SOAP_ROL_GRUBU[rol]] : null
  if (!g) return null
  const [b, s, k] = BASLIK[dil]
  return [b, s, ...g.bolumler.map((x) => x[dil]), k, ...g.kirilmaz.map((x) => `• ${x[dil]}`)].join('\n')
}
